/**
 * Provenance records — the pure part (no IO).
 *
 * A provenance object is the machine-readable statement "this output was
 * generated by an AI system": a spec tag, the generator, the model, an output
 * id, a time and a hash of the content. The same object, minus `verify`, is the
 * small record the {@link ProvenanceStore} keeps so that "did this exact text
 * come from this installation?" can be answered later. It never holds the text.
 *
 * The object is kind-aware so that media records (#3328: `image`, `audio`,
 * `normalization: 'none'`, `digital_source_type`) and watermark detection
 * (#3331: `model.watermark.key_id`) extend it without reshaping it. `kind` is
 * omitted for text, the default.
 *
 * @module services/provenance/records
 */
import { createHash, randomBytes } from 'node:crypto';

/** Spec tag of the object. */
export const PROVENANCE_SPEC = 'intrafind-provenance/1.0';

/** Hash algorithm of `content_hash`. */
export const HASH_ALG = 'sha-256';

/**
 * Frozen text normalization of the hash. A change is a new name
 * (`nfc-trim-2`), never a redefinition: records already stored were hashed with
 * the algorithm their `normalization` names.
 */
export const NORMALIZATION_NFC_TRIM = 'nfc-trim';

/** Normalization of raw bytes (media records, #3328). */
export const NORMALIZATION_NONE = 'none';

/** Normalizations {@link hashContent} and the verify endpoint understand. */
export const TEXT_NORMALIZATIONS = Object.freeze([NORMALIZATION_NFC_TRIM]);

/** Kinds of output a record can describe. */
export const PROVENANCE_KINDS = Object.freeze(['text', 'image', 'audio']);

/** Marking schemes a model's `contentMarking.<kind>.by` can name. */
export const MARKING_BY = Object.freeze(['ihub', 'provider', 'none']);

const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

/**
 * A new output id: a ULID (48-bit millisecond time + 80 random bits, Crockford
 * base32, sortable). Allocated before the first byte of a response so it can go
 * into a header; never derived from the content.
 *
 * @param {number} [now] - Millisecond timestamp (tests).
 * @returns {string} 26 characters
 */
export function newOutputId(now = Date.now()) {
  let time = Math.floor(now);
  let timePart = '';
  for (let i = 0; i < 10; i += 1) {
    timePart = CROCKFORD[time % 32] + timePart;
    time = Math.floor(time / 32);
  }
  const bytes = randomBytes(10);
  let bits = 0n;
  for (const byte of bytes) bits = (bits << 8n) | BigInt(byte);
  let randomPart = '';
  for (let i = 0; i < 16; i += 1) {
    randomPart = CROCKFORD[Number(bits & 31n)] + randomPart;
    bits >>= 5n;
  }
  return timePart + randomPart;
}

/** Whether a value looks like an output id minted by {@link newOutputId}. */
export function isOutputId(value) {
  return typeof value === 'string' && /^[0-9A-HJKMNP-TV-Z]{26}$/.test(value);
}

/**
 * The `nfc-trim` normalization: (1) Unicode NFC, (2) `\r\n` and lone `\r`
 * become `\n`, (3) leading and trailing whitespace is trimmed. Inner
 * whitespace, case and Markdown are left alone.
 *
 * @param {string} text
 * @returns {string}
 */
export function normalizeText(text) {
  return String(text ?? '')
    .normalize('NFC')
    .replace(/\r\n?/g, '\n')
    .trim();
}

/**
 * Lowercase hex SHA-256 of a text under `normalization`.
 *
 * @param {string} text
 * @param {string} [normalization]
 * @returns {string}
 * @throws {Error} For a normalization this version does not know.
 */
export function hashText(text, normalization = NORMALIZATION_NFC_TRIM) {
  if (normalization !== NORMALIZATION_NFC_TRIM) {
    throw new Error(`Unknown normalization: ${normalization}`);
  }
  return createHash('sha256').update(normalizeText(text), 'utf8').digest('hex');
}

/** Whether a string is a lowercase 64-character hex digest. */
export function isHexHash(value) {
  return typeof value === 'string' && /^[0-9a-f]{64}$/.test(value);
}

/**
 * What a model declares about its output marking. A model without the key is
 * `{ by: 'none' }` everywhere in code, so a hand-written model file still works.
 *
 * @param {Object} [modelConfig]
 * @param {string} [kind='text']
 * @returns {{by: string, scheme?: string, keyId?: string, statementRef?: string}}
 */
export function getContentMarking(modelConfig, kind = 'text') {
  const marking = modelConfig?.contentMarking?.[kind];
  if (!marking || !MARKING_BY.includes(marking.by)) return { by: 'none' };
  return marking;
}

/**
 * The public `model.watermark` member. `provider` is `applied: true` on the
 * strength of the operator's written statement (we cannot check it); `ihub` is
 * `applied: true` only when the generation path reports that the watermark was
 * requested, not greedy and not structured output (`planTextWatermark`); `none` is false. `statementRef` stays out of the public object.
 *
 * @param {Object} [modelConfig]
 * @param {Object} [options]
 * @param {string} [options.kind]
 * @param {boolean} [options.watermarkApplied] - Reported by the generation path.
 * @param {string} [options.keyId] - Watermark key id actually used (#3331).
 * @param {string} [options.watermarkReason] - Why `applied` is false (#3331).
 * @returns {{by: string, scheme?: string, key_id?: string, applied: boolean}}
 */
export function buildWatermark(
  modelConfig,
  { kind = 'text', watermarkApplied, keyId, watermarkReason } = {}
) {
  const marking = getContentMarking(modelConfig, kind);
  if (marking.by === 'none') return { by: 'none', applied: false };
  const watermark = { by: marking.by };
  if (marking.scheme) watermark.scheme = marking.scheme;
  if (marking.by === 'ihub') {
    const used = keyId || marking.keyId;
    if (used) watermark.key_id = used;
    watermark.applied = watermarkApplied === true;
    // Why a requested mark is not claimed: greedy, structured_output, no_active_key.
    if (!watermark.applied && watermarkReason) watermark.reason = watermarkReason;
  } else {
    if (marking.keyId) watermark.key_id = marking.keyId;
    watermark.applied = true;
  }
  return watermark;
}

/**
 * Build the provenance object (spec-defined, snake_case).
 *
 * @param {Object} input
 * @param {string} input.outputId
 * @param {string} [input.createdAt] - ISO time; default now.
 * @param {string} [input.text] - Output text; hashed, never kept. Omit for a
 *   tool-call-only output: the object then has no `content_hash`.
 * @param {string} [input.hash] - A precomputed hash (media), with `normalization`.
 * @param {string} [input.normalization]
 * @param {string} [input.kind='text']
 * @param {Object} input.model - `{ id }` of the generating model or workflow.
 * @param {Object} [input.modelConfig] - Model config, for `contentMarking`.
 * @param {boolean} [input.watermarkApplied]
 * @param {string} input.installationId
 * @param {string} input.version
 * @param {string} [input.verifyUrl] - Absolute verify URL (response time only).
 * @returns {Object}
 */
export function buildProvenance({
  outputId,
  createdAt = new Date().toISOString(),
  text,
  hash,
  normalization,
  kind = 'text',
  model,
  modelConfig,
  watermarkApplied,
  keyId,
  watermarkReason,
  installationId,
  version,
  verifyUrl
}) {
  const object = {
    spec: PROVENANCE_SPEC,
    ai_generated: true,
    generator: { product: 'iHub Apps', version, installation_id: installationId },
    model: {
      id: model?.id ?? null,
      watermark: buildWatermark(modelConfig, { kind, watermarkApplied, keyId, watermarkReason })
    },
    output_id: outputId,
    created_at: createdAt
  };
  if (kind !== 'text') object.kind = kind;
  if (isHexHash(hash)) {
    object.content_hash = {
      alg: HASH_ALG,
      normalization: normalization || NORMALIZATION_NONE,
      value: hash
    };
  } else if (typeof text === 'string' && normalizeText(text) !== '') {
    object.content_hash = {
      alg: HASH_ALG,
      normalization: NORMALIZATION_NFC_TRIM,
      value: hashText(text)
    };
  }
  if (verifyUrl) object.verify = verifyUrl;
  return object;
}

/** The stored form of a provenance object: everything but the response-time `verify` URL. */
export function toStoredRecord(provenance) {
  const { verify: _verify, ...record } = provenance || {};
  return record;
}
